public class RoundRobinTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            int[] needs = {1, 2, 1};
            check("example from the task", "[Ann, Cal, Ben]",
                    String.valueOf(RoundRobin.serveOrder(new String[]{"Ann", "Ben", "Cal"}, needs)));
            check("needs array not modified", "[1, 2, 1]", Arrays.toString(needs));

            check("all need one turn", "[A, B, C]",
                    String.valueOf(RoundRobin.serveOrder(new String[]{"A", "B", "C"}, new int[]{1, 1, 1})));
            check("reverse workloads", "[B, C, A]",
                    String.valueOf(RoundRobin.serveOrder(new String[]{"A", "B", "C"}, new int[]{3, 1, 2})));
            check("single person, many turns", "[Solo]",
                    String.valueOf(RoundRobin.serveOrder(new String[]{"Solo"}, new int[]{4})));
            check("nobody in line", "[]",
                    String.valueOf(RoundRobin.serveOrder(new String[]{}, new int[]{})));
            check("equal heavy loads finish in line order", "[X, Y]",
                    String.valueOf(RoundRobin.serveOrder(new String[]{"X", "Y"}, new int[]{2, 2})));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
